import{c as l,Z as e,Q as r,j as s,m as n,o}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"木瓜","description":"","frontmatter":{"title":"木瓜","author":"佚名","dynasty":"先秦"},"headers":[],"relativePath":"books/shici/shijing/8.md","filePath":"books/shici/shijing/8.md"}'),h={name:"books/shici/shijing/8.md"};function p(c,a,d,u,_,m){const i=e("PoemAuthor"),t=e("PoemNav");return r(),s("div",null,[a[0]||(a[0]=n('<h1 id="木瓜" tabindex="-1">木瓜 <a class="header-anchor" href="#木瓜" aria-label="Permalink to &quot;木瓜&quot;">​</a></h1><p><strong>[先秦] 佚名</strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>投我以木瓜，报之以琼琚。匪报也，永以为好也。</p><p>投我以木桃，报之以琼瑶。匪报也，永以为好也。</p><p>投我以木李，报之以琼玖。匪报也，永以为好也。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>投：赠送</li><li>木瓜：一种落叶灌木的果实</li><li>琼琚：美玉</li><li>匪：通&quot;非&quot;</li><li>永以为好：永远结好</li><li>木桃：果名，即樝子</li><li>琼瑶：美玉</li><li>木李：果名，即榠樝</li><li>琼玖：美玉</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>你赠送我木瓜，我回赠你美玉。这不是回报，是表示永远相好。</p><p>你赠送我木桃，我回赠你美玉。这不是回报，是表示永远相好。</p><p>你赠送我木李，我回赠你美玉。这不是回报，是表示永远相好。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是《诗经》中的名篇，描写了朋友之间相互赠答的情景，表达了深厚的情谊和对友谊的珍视。</p><p>全诗三章，结构相似，反复咏唱。每章都以&quot;投我以……，报之以……&quot;的句式开头，写朋友之间的相互赠答。对方赠送的是木瓜、木桃、木李等普通的果实，而回赠的却是琼琚、琼瑶、琼玖等珍贵的美玉。这种不对等的赠答，正是为了表达&quot;匪报也，永以为好也&quot;的深意——回赠不是为了报答，而是为了表示永远相好的心意。</p><p>这种重情轻物的态度，体现了古人对友谊的珍视。在古人看来，情谊的价值远超过物质的价值，朋友之间的情谊是无价的。</p><p>全诗语言朴素，情感真挚，将友谊的深厚和珍贵表现得淋漓尽致。后世&quot;投桃报李&quot;的成语，即源于此诗。</p>',17)),o(i,{name:"《诗经》",years:"西周初年至春秋中叶",desc:"中国最早的诗歌总集，收录了西周初年至春秋中叶（前11世纪至前6世纪）的诗歌305篇，分为“风”“雅”“颂”三部分。《诗经》内容丰富，反映了周代社会生活的方方面面，是中国现实主义文学的源头。",link:"/books/shici/shijing","is-shijing":""}),o(t)])}const f=l(h,[["render",p]]);export{b as __pageData,f as default};
